//! Module: keyway_core::code_pages
//! Purpose: Embedded OEM and ANSI code page tables and the layout to page mapping.
//! Created: 2026-11-08
//! Architecture: The agent decodes Alt codes through these; the tables under
//! data/code_pages are generated by tools/generate_code_pages.py.

use crate::layout_id::LayoutId;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fmt;

const BYTES_PER_PAGE: usize = 256;
const CELLS_PER_ROW: usize = 16;
const ROWS_PER_PAGE: usize = BYTES_PER_PAGE / CELLS_PER_ROW;
const UNDEFINED_CELL: &str = "----";
const COMMENT_PREFIX: char = '#';
const HEXADECIMAL: u32 = 16;

macro_rules! embedded_page {
    ($number:literal) => {
        (
            $number,
            include_str!(concat!("../../../data/code_pages/cp", $number, ".txt")),
        )
    };
}

const EMBEDDED_PAGES: &[(u16, &str)] = &[
    embedded_page!(437),
    embedded_page!(720),
    embedded_page!(737),
    embedded_page!(775),
    embedded_page!(850),
    embedded_page!(852),
    embedded_page!(855),
    embedded_page!(857),
    embedded_page!(858),
    embedded_page!(860),
    embedded_page!(861),
    embedded_page!(862),
    embedded_page!(863),
    embedded_page!(864),
    embedded_page!(865),
    embedded_page!(866),
    embedded_page!(869),
    embedded_page!(874),
    embedded_page!(1250),
    embedded_page!(1251),
    embedded_page!(1252),
    embedded_page!(1253),
    embedded_page!(1254),
    embedded_page!(1255),
    embedded_page!(1256),
    embedded_page!(1257),
    embedded_page!(1258),
];

const EMBEDDED_LAYOUT_PAGES: &str = include_str!("../../../data/layout_code_pages.toml");

/// The number of a code page embedded in this build; other numbers cannot be built.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(try_from = "u16", into = "u16")]
pub struct CodePageId(u16);

impl TryFrom<u16> for CodePageId {
    type Error = String;

    fn try_from(number: u16) -> Result<Self, Self::Error> {
        if EMBEDDED_PAGES
            .iter()
            .any(|(embedded, _text)| *embedded == number)
        {
            Ok(Self(number))
        } else {
            Err(format!("unsupported code page: {number}"))
        }
    }
}

impl From<CodePageId> for u16 {
    fn from(id: CodePageId) -> Self {
        id.0
    }
}

/// The two code pages that a layout's Alt codes use.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CodePagePair {
    pub oem: CodePageId,
    pub ansi: CodePageId,
}

#[derive(Clone, Debug)]
pub struct CodePageTable {
    characters: [Option<char>; BYTES_PER_PAGE],
}

impl CodePageTable {
    /// Returns the character for a byte, or None when the page leaves it undefined.
    pub fn decode(&self, byte: u8) -> Option<char> {
        self.characters[usize::from(byte)]
    }

    fn parse(page: u16, text: &str) -> Result<Self, CodePageError> {
        let mut characters = [None; BYTES_PER_PAGE];
        let mut rows_read = 0;

        for (line_index, line) in text.lines().enumerate() {
            if line.is_empty() || line.starts_with(COMMENT_PREFIX) {
                continue;
            }

            let malformed = || CodePageError {
                page,
                line: line_index + 1,
            };
            let (label, cells) = line.split_once(':').ok_or_else(malformed)?;
            let row_start = usize::from_str_radix(label, HEXADECIMAL).map_err(|_| malformed())?;
            let cells: Vec<&str> = cells.split_whitespace().collect();

            if row_start != rows_read * CELLS_PER_ROW || cells.len() != CELLS_PER_ROW {
                return Err(malformed());
            }

            for (offset, cell) in cells.iter().enumerate() {
                characters[row_start + offset] = parse_cell(cell).ok_or_else(malformed)?;
            }

            rows_read += 1;
        }

        if rows_read != ROWS_PER_PAGE {
            return Err(CodePageError {
                page,
                line: text.lines().count(),
            });
        }

        Ok(Self { characters })
    }
}

/// Returns the cell's character, Some(None) for an undefined cell, or None if invalid.
fn parse_cell(cell: &str) -> Option<Option<char>> {
    if cell == UNDEFINED_CELL {
        return Some(None);
    }

    let scalar = u32::from_str_radix(cell, HEXADECIMAL).ok()?;

    char::from_u32(scalar).map(Some)
}

/// A malformed embedded table, which means this build's data files are broken.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CodePageError {
    pub page: u16,
    pub line: usize,
}

impl fmt::Display for CodePageError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "malformed code page table cp{}, line {}",
            self.page, self.line
        )
    }
}

impl std::error::Error for CodePageError {}

/// All embedded code page tables, parsed once when the agent starts.
#[derive(Clone, Debug)]
pub struct CodePageCatalog {
    tables: BTreeMap<u16, CodePageTable>,
}

impl CodePageCatalog {
    pub fn load() -> Result<Self, CodePageError> {
        let mut tables = BTreeMap::new();

        for (page, text) in EMBEDDED_PAGES {
            tables.insert(*page, CodePageTable::parse(*page, text)?);
        }

        Ok(Self { tables })
    }

    pub fn table(&self, id: CodePageId) -> Option<&CodePageTable> {
        self.tables.get(&id.0)
    }
}

/// The default mapping from XKB layouts to code pages.
#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LayoutCodePages {
    default: CodePagePair,
    layouts: BTreeMap<LayoutId, CodePagePair>,
}

impl LayoutCodePages {
    pub fn load() -> Result<Self, toml::de::Error> {
        toml::from_str(EMBEDDED_LAYOUT_PAGES)
    }

    /// Finds a layout's pages: user overrides win over the embedded mapping, and an
    /// exact layout+variant match wins over the plain layout.
    pub fn pages_for(
        &self,
        layout: &LayoutId,
        overrides: &BTreeMap<LayoutId, CodePagePair>,
    ) -> CodePagePair {
        let lookup = |table: &BTreeMap<LayoutId, CodePagePair>| {
            let find_base = || {
                let base = table
                    .iter()
                    .find(|(id, _pages)| id.as_str() == layout.base());

                base.map(|(_id, pages)| *pages)
            };

            table.get(layout).copied().or_else(find_base)
        };

        lookup(overrides)
            .or_else(|| lookup(&self.layouts))
            .unwrap_or(self.default)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn layout(id: &str) -> LayoutId {
        LayoutId::try_from(id.to_string()).unwrap()
    }

    fn pair(oem: u16, ansi: u16) -> CodePagePair {
        CodePagePair {
            oem: CodePageId::try_from(oem).unwrap(),
            ansi: CodePageId::try_from(ansi).unwrap(),
        }
    }

    #[test]
    fn every_embedded_table_parses() {
        let catalog = CodePageCatalog::load().unwrap();

        assert_eq!(catalog.tables.len(), EMBEDDED_PAGES.len());
    }

    #[test]
    fn tables_match_the_published_code_pages() {
        let catalog = CodePageCatalog::load().unwrap();
        let decode = |page: u16, byte: u8| {
            let id = CodePageId::try_from(page).unwrap();

            catalog.table(id).unwrap().decode(byte)
        };

        assert_eq!(decode(437, 0x82), Some('é'));
        assert_eq!(decode(850, 0x9B), Some('ø'));
        assert_eq!(decode(737, 0x98), Some('α'));
        assert_eq!(decode(866, 0x80), Some('А'));
        assert_eq!(decode(1252, 0x80), Some('€'));
        assert_eq!(decode(1253, 0xE1), Some('α'));
        assert_eq!(decode(1251, 0xC0), Some('А'));
        assert_eq!(decode(1250, 0xA3), Some('Ł'));
    }

    #[test]
    fn oem_control_bytes_are_glyphs_and_ansi_control_bytes_are_not() {
        let catalog = CodePageCatalog::load().unwrap();
        let oem = catalog.table(CodePageId::try_from(437).unwrap()).unwrap();
        let ansi = catalog.table(CodePageId::try_from(1252).unwrap()).unwrap();

        assert_eq!(oem.decode(0x01), Some('☺'));
        assert_eq!(oem.decode(0x7F), Some('⌂'));
        assert_eq!(ansi.decode(0x01), Some('\u{1}'));
        assert_eq!(ansi.decode(0x81), None);
    }

    #[test]
    fn malformed_tables_are_reported_with_their_line() {
        let short_row = "00: 0041 0042\n";
        let error = CodePageTable::parse(1, short_row).unwrap_err();

        assert_eq!(error, CodePageError { page: 1, line: 1 });
    }

    #[test]
    fn unsupported_page_numbers_cannot_be_built() {
        assert!(CodePageId::try_from(932).is_err());
    }

    #[test]
    fn lookup_prefers_overrides_then_variant_then_layout_then_default() {
        let pages = LayoutCodePages::load().unwrap();
        let no_overrides = BTreeMap::new();
        let overrides = BTreeMap::from([(layout("gr"), pair(869, 1253))]);

        assert_eq!(
            pages.pages_for(&layout("br"), &no_overrides),
            pair(850, 1252)
        );
        assert_eq!(
            pages.pages_for(&layout("gr+simple"), &no_overrides),
            pair(737, 1253)
        );
        assert_eq!(
            pages.pages_for(&layout("rs"), &no_overrides),
            pair(855, 1251)
        );
        assert_eq!(
            pages.pages_for(&layout("rs+latin"), &no_overrides),
            pair(852, 1250)
        );
        assert_eq!(
            pages.pages_for(&layout("jp"), &no_overrides),
            pair(437, 1252)
        );
        assert_eq!(
            pages.pages_for(&layout("gr+simple"), &overrides),
            pair(869, 1253)
        );
    }
}
